function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -50 || v > 50)) return 'Each value is an integer from -50 to 50.';
  if (!Number.isInteger(target) || target < -50 || target > 50) return 'target is an integer from -50 to 50.';
  return null;
}

