function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 9);
  const span = size === 'large' || rand() < 0.5 ? 50 : 4;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  const target = Math.floor(rand() * 101) - 50;
  return [nums, target];
}
